# Re-run the prediction correctly - both passes work on the same output grid
def endpoint_preserve_fill(input_grid):
    output = [row[:] for row in input_grid]
    grid_rows = len(input_grid)
    grid_cols = len(input_grid[0])

    # Horizontal pass
    for r in range(grid_rows):
        i = 0
        while i < grid_cols:
            if input_grid[r][i] == 1:
                j = i
                while j < grid_cols and input_grid[r][j] == 1:
                    j += 1
                # Group is [i, j)
                for k in range(i + 1, j - 1):
                    output[r][k] = 2
                i = j
            else:
                i += 1

    # Vertical pass
    for c in range(grid_cols):
        i = 0
        while i < grid_rows:
            if input_grid[i][c] == 1:
                j = i
                while j < grid_rows and input_grid[j][c] == 1:
                    j += 1
                # Group is [i, j)
                for k in range(i + 1, j - 1):
                    output[k][c] = 2
                i = j
            else:
                i += 1

